| Some b => if Nat.eqb b base then YQ0b.mkRegion (YQ0b.r_base r) (YQ0b.r_lo r) (YQ0b.r_hi r) (YQ0b.r_wlo r) (YQ0b.r_whi r)
(map (chunk_redesc off e) (YQ0b.r_chunks r)) else r
| None => r end) (ss_mem s)).
Definition fl_R2_deads : list nat := [10; 24; 11]%nat.
Definition fl_R2_deads_bv : list (bv 5) := [10; 24; 11]%bv.
Definition INV_R2 (B : asyms) : flcx -> env -> Z -> alayout -> astate -> world trbsegs -> machine_state -> Model -> Prop :=
fun cx E k ly3 S3 W3 ms3 md3 =>
(exists gen, ew E 180 = Z_to_bv 64 gen /\ 0 <= gen < 2 ^ 32) /\ ew E 184 = Z_to_bv 64 (fl_npal cx) /\
exists pt w h top left tidx img,
ew E 451 = Z_to_bv 64 pt /\ ew E 403 = Z_to_bv 64 w /\ ew E 404 = Z_to_bv 64 h /\ ew E 400 = Z_to_bv 64 top /\
ew E 405 = Z_to_bv 64 left /\ ew E 401 = Z_to_bv 64 tidx /\ ew E 450 = Z_to_bv 64 img /\ 0 <= pt < 2 ^ 64 /\
1 <= w /\ 0 <= left /\ left + w <= cg_W (c_s cx) /\ 1 <= h /\ 0 <= top /\ top + h <= cg_H (c_s cx) /\ 0 <= tidx < 2 ^ 64 /\
((pt = 0 /\ img = fr_img (c_f cx) /\ k <= 0 /\ ablocks B ly3 S3 = ablocks B (c_ly cx) (c_S cx)) \/
(pt <> 0 /\ img = pt /\ k <= 2 /\ fl_tmpblk B cx pt (w * h) ly3 S3)).
