Definition region_filter_offs (keep : list Z) (r : YQ0b.region) : YQ0b.region :=
YQ0b.mkRegion (YQ0b.r_base r) (YQ0b.r_lo r) (YQ0b.r_hi r) (YQ0b.r_wlo r) (YQ0b.r_whi r)
(filter (fun c => existsb (Z.eqb (YQ0b.c_off c)) keep) (YQ0b.r_chunks r)).
Definition fl_X_mem (m : smem) : smem :=
map (fun r => match YQ0b.r_base r with
| Some b => if Nat.eqb b 75 then region_filter_offs [0; 8; 16; 120] r
else if Nat.eqb b 70 then region_filter_offs [112] r else r
| None => r end) m.
