Definition INV_X (B : asyms) : flcx -> env -> Z -> alayout -> astate -> world trbsegs -> machine_state -> Model -> Prop :=
fun cx E k ly3 S3 W3 ms3 md3 =>
k <= EV_FLUSH /\ (exists r, ew E 520 = Z_to_bv 64 r /\ 0 <= r < 2 ^ 64) /\
Permutation (ablocks B ly3 S3) (ablocks B (c_ly cx) (c_S cx)).
Definition INV_R5 (B : asyms) : flcx -> env -> Z -> alayout -> astate -> world trbsegs -> machine_state -> Model -> Prop :=
fun cx E k ly3 S3 W3 ms3 md3 =>
k <= 2 + EV_RAWADD /\ (exists res, ew E 479 = Z_to_bv 64 res /\ 0 <= res < 2 ^ 64) /\
exists pt, ew E 451 = Z_to_bv 64 pt /\ 0 <= pt < 2 ^ 64 /\
((pt = 0 /\ Permutation (ablocks B ly3 S3) (ablocks B (c_ly cx) (c_S cx))) \/
(pt <> 0 /\ exists n, 0 <= n /\ Permutation (ablocks B ly3 S3) (ablocks B (c_ly cx) (c_S cx) ++ [(pt, n)]) /\
aftok (fl_FP cx) (ablocks B (c_ly cx) (c_S cx)) (pt, n))).
End a.
